/bin/bash -lc "python - <<'PY'
import gzip, math, itertools, re
from collections import OrderedDict

rna_path='inputs/multiome.match.atac.rna.q1.rna.tsv.gz'
atac_path='inputs/multiome.match.atac.rna.q1.atac.tsv.gz'
gtf='gencode.v44.annotation.gtf.gz'

def op(path):
    return gzip.open(path,'rt') if path.endswith('.gz') else open(path)

def attrs(s):
    d={}
    for m in re.finditer(r'(\\S+) \"(["'^"]*)";'"', s):
        d[m.group(1)]=m.group(2)
    return d

gene_bin={}
with gzip.open(gtf,'rt') as f:
    for line in f:
        if line.startswith('#'): continue
        p=line.rstrip('\\n').split('\\t')
        if len(p)<9 or p[2] "'!= '"'gene': continue
        chrom=p[0]
        if not chrom.startswith('chr'): continue
        a=attrs(p[8]); name=a.get('gene_name')
        if not name or name in gene_bin: continue
        start=int(p[3]); end=int(p[4]); strand=p[6]
        pos=(start-1) if strand=='+' else (end-1)
        b=(pos//10000)*10000
        gene_bin[name]=f'{chrom}_{b}_{b+10000}'

rna={}
with gzip.open(rna_path,'rt') as f:
    header=f.readline().rstrip('\\n').split('\\t')[1:]
    for line in f:
        p=line.rstrip('\\n').split('\\t')
        if p[0] in gene_bin:
            rna[p[0]]=[math.log1p(float(x)) for x in p[1:]]
needed_bins=set(gene_bin[g] for g in rna)
atac_bins={}
with gzip.open(atac_path,'rt') as f:
    ahead=f.readline().rstrip('\\n').split('\\t')[1:]
    for line in f:
        p=line.rstrip('\\n').split('\\t')
        if p[0] in needed_bins:
            atac_bins[p[0]]=[math.log1p(float(x)) for x in p[1:]]

genes=[]; R=[]; A=[]
seen=set()
for g, rv in rna.items():
    b=gene_bin[g]
    if b in atac_bins and g not in seen:
        genes.append(g); R.append(rv); A.append(atac_bins[b]); seen.add(g)
print('matched genes',len(genes),'rna genes',len(rna),'atac bins',len(atac_bins))

def corr(xs,ys):
    n=len(xs); mx=sum(xs)/n; my=sum(ys)/n
    num=sum((x-mx)*(y-my) for x,y in zip(xs,ys))
    vx=sum((x-mx)**2 for x in xs); vy=sum((y-my)**2 for y in ys)
    return num/math.sqrt(vx*vy) if vx>0 and vy>0 else 0
M=[]
for i in range(8):
    row=[]
    xs=[r[i] for r in R]
    for j in range(8):
        ys=[a[j] for a in A]
